from pathlib import Path
root=Path(__file__).resolve().parents[1]
css=(root/'src/styles.css').read_text().replace("@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');",'')
html=r'''<!doctype html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Preview Offline — Portal Standar Biaya</title><meta name="description" content="Prototype interaktif Portal Kamus Standar Biaya, tidak menggunakan data resmi."><style>__STYLES__
.preview-small{font-size:12px;color:#cde1ed}.preview-top-logo{display:flex;align-items:center;gap:10px}.preview-tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.preview-content{min-height:55vh}.preview-hero-nav{font-size:12px;display:flex;align-items:center;gap:8px;color:#d9e7ef}.preview-table-btn{padding:8px 13px;border:1px solid #d5e2ed;border-radius:6px;background:white;color:#1c5784;font-weight:800;font-size:12px}.preview-page-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:22px}.preview-page-heading h2{margin:0;font-size:21px}.preview-tabs{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}.preview-tabs button{border:1px solid #d7e2eb;background:#fff;color:#4d6175;border-radius:30px;padding:9px 15px;font-size:12px;font-weight:800}.preview-tabs button.active{background:#163d63;color:white}.preview-tip{padding:15px;background:#fff8e9;border:1px solid #e9dcb8;border-radius:8px;color:#81652e;font-size:12px;margin-top:18px}.preview-bar{height:12px;background:#eef3f8;overflow:hidden;border-radius:6px}.preview-bar span{display:block;height:100%;background:#245b87;border-radius:6px}.preview-chart-row{display:grid;grid-template-columns:150px 1fr 36px;align-items:center;gap:13px;margin:22px 0;font-size:13px}.preview-chart-row b{text-align:right}.preview-dashboard-panel{padding:25px;border:1px solid #e5ebef;border-radius:10px;background:#fff}.preview-faq-content{border-top:1px solid #e2e7ec;padding:15px 20px;background:#fafcfd;font-size:13px;color:#63778b}.preview-btn-inline{display:inline-flex;align-items:center;gap:7px;padding:12px 17px;background:#dbb86f;color:#132d4b;border:0;border-radius:8px;font-size:12px;font-weight:800}.preview-btn-inline:hover{background:#e9c987}.preview-art-number{font-size:34px;line-height:1;color:#e5c888;font-weight:800}.preview-navy-card{background:#0f2f51;color:white;padding:30px;border-radius:13px}.preview-navy-card p{color:#c4d4df}.preview-route{cursor:pointer}.preview-small-icon{font-size:24px}.preview-breadcrumb{color:#d4e4ef;font-size:12px;margin-bottom:20px;cursor:pointer}.preview-no-link{cursor:default!important;color:#95a0aa!important}.preview-pill{padding:7px 12px;border-radius:6px;background:#e9f3fb;color:#1d5681;font-size:11px;font-weight:800}.preview-form{display:flex;gap:12px;margin-bottom:15px}.preview-form input{border:1px solid #dae6ed;border-radius:8px;flex:1;min-width:0;padding:13px 15px;outline:none}.preview-form select{min-width:160px;border:1px solid #dae6ed;border-radius:8px;padding:11px;background:white}.preview-link-btn{border:0;background:transparent;color:#1d5a85;font-size:13px;font-weight:800;cursor:pointer;text-align:left}.preview-line{padding:19px 0;border-bottom:1px solid #e9eef2}.preview-line h3{font-size:15px;margin:0 0 8px}.preview-line p{font-size:12px;color:#6b7f90;margin:0}.preview-print{padding:10px 14px;border:1px solid #cfdce8;background:white;border-radius:7px;color:#276087;font-size:12px;cursor:pointer}.preview-footer-note{font-size:11px;color:#8492a1}.preview-summary-wrap{margin-top:25px;display:grid;grid-template-columns:repeat(3,1fr);gap:15px}@media(max-width:800px){.preview-tiles{grid-template-columns:1fr}.preview-summary-wrap{grid-template-columns:repeat(2,1fr)}}@media(max-width:520px){.preview-form{flex-direction:column}.preview-form select{width:100%}.preview-summary-wrap{grid-template-columns:1fr}.preview-chart-row{grid-template-columns:100px 1fr 30px}}
</style></head><body><div class="top-stripe"></div><header class="site-header"><div class="container header-inner"><a class="brand preview-route" data-page="home"><span class="brand-icon">▤</span><span><b>PORTAL STANDAR BIAYA</b><small>Pusat Informasi & Kamus Standar Biaya</small></span></a><nav class="nav-links" id="nav"><a class="nav-link preview-route active" data-page="home">Beranda</a><a class="nav-link preview-route" data-page="mengenal">Mengenal SB</a><a class="nav-link preview-route" data-page="kamus">Kamus Biaya</a><a class="nav-link preview-route" data-page="regulasi">Regulasi</a><a class="nav-link preview-route" data-page="dashboard">Dashboard</a><a class="nav-link preview-route" data-page="pustaka">Pustaka</a><a class="nav-link preview-route" data-page="faq">FAQ</a></nav><button class="mobile-toggle" id="hamburger" aria-label="Buka menu">☰</button></div></header><div class="demo-alert"><div class="container">MODE DEMONSTRASI — Data item, statistik dan referensi yang ditampilkan hanyalah contoh, bukan nilai atau ketentuan resmi Kementerian Keuangan.</div></div><main class="preview-content" id="app"></main><footer class="footer"><div class="container footer-grid"><div><div class="footer-logo">▤ Portal Standar Biaya</div><p>Konsep pusat informasi dan kamus digital standar biaya yang dapat diakses secara luas.</p><small>Prototype demonstrasi offline. Tidak terhubung Google Sheets/Drive atau situs resmi.</small></div><div><b>Navigasi</b><a class="preview-route" data-page="kamus">Kamus Biaya</a><a class="preview-route" data-page="regulasi">Regulasi</a><a class="preview-route" data-page="dashboard">Dashboard</a></div><div><b>Informasi</b><a class="preview-route" data-page="mengenal">Tentang Standar Biaya</a><a class="preview-route" data-page="faq">Tanya Jawab</a></div></div><div class="container footer-bottom">Preview Portal Standar Biaya • Tidak untuk acuan penganggaran</div></footer>
<script>
const ITEMS=[
{id:'DEMO-001',jenis:'SBM',nama:'Honorarium Narasumber/Pembahas/Pakar',kelompok:'Honorarium',satuan:'OJ',desc:'Contoh item untuk memperagakan halaman detail. Definisi dan ketentuan riil harus merujuk regulasi tahun terkait.'},
{id:'DEMO-002',jenis:'SBM',nama:'Biaya Penginapan Perjalanan Dinas',kelompok:'Perjalanan Dinas',satuan:'OH',desc:'Contoh item biaya penginapan perjalanan dinas. Besaran, kategori, dan wilayah belum diisi.'},
{id:'DEMO-003',jenis:'SBM',nama:'Biaya Transportasi Perjalanan Dinas',kelompok:'Perjalanan Dinas',satuan:'Orang/Kali',desc:'Contoh entri transportasi untuk menguji navigasi portal.'},
{id:'DEMO-004',jenis:'SBK',nama:'Standar Biaya Keluaran (contoh)',kelompok:'Keluaran',satuan:'Output',desc:'Contoh kelompok biaya keluaran, bukan item resmi.'},
{id:'DEMO-005',jenis:'SSB',nama:'Standar Struktur Biaya (contoh)',kelompok:'Struktur Biaya',satuan:'Persentase',desc:'Contoh informasi struktur biaya.'},
{id:'DEMO-006',jenis:'SBM',nama:'Konsumsi Rapat (contoh)',kelompok:'Konsumsi',satuan:'Orang/Kali',desc:'Contoh entri konsumsi rapat untuk demonstrasi.'}
];
const REGS=[{jenis:'PMK',tahun:'2026',nomor:'CONTOH',judul:'Contoh kartu regulasi standar biaya — belum berisi peraturan resmi',status:'Contoh'},{jenis:'KMK',tahun:'2025',nomor:'CONTOH',judul:'Contoh referensi kebijakan — placeholder pustaka regulasi',status:'Contoh'}];
const DOCS=[{kategori:'Paparan',tahun:'2026',judul:'Pengantar Standar Biaya',ket:'Placeholder untuk bahan paparan yang telah memperoleh persetujuan publikasi.'},{kategori:'Pedoman',tahun:'2026',judul:'Pedoman Penggunaan Portal',ket:'Placeholder untuk panduan dan materi sosialisasi.'},{kategori:'Kajian',tahun:'2026',judul:'Kajian Standar Biaya',ket:'Placeholder untuk kajian yang telah dinyatakan terbuka untuk publik.'}];
const FAQ=[['Apa itu kamus standar biaya?','Kamus membantu menelusuri item, kategori, satuan, tahun, ketentuan dan dasar hukum dalam satu situs.'],['Apakah besaran biaya sama setiap tahun?','Tidak selalu. Besaran dan ruang lingkup mengikuti regulasi sesuai tahun anggaran dan kondisi yang berlaku.'],['Dari mana data portal berasal?','Dalam rencana production, data terstruktur bersumber dari Google Sheets dan dokumen dari Google Drive setelah verifikasi serta persetujuan publikasi.']];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=t=>`<span class="badge ${t==='SBM'?'pill-sbm':t==='SBK'?'pill-sbk':t==='SSB'?'pill-ssb':'muted'}">${esc(t)}</span>`;
const pageHero=(label,title,sub)=>`<section class="page-hero"><div class="container"><span class="eyebrow">${label}</span><h1>${title}</h1><p>${sub}</p></div></section>`;
const card=(x)=>`<a class="type-card preview-route" data-page="kamus" data-jenis="${x.jenis}"><span class="type-icon ${x.cls}"><span class="preview-small-icon">${x.icon}</span></span><h3>${x.title}</h3><p>${x.desc}</p><div>Jelajahi ${x.jenis} →</div></a>`;
let page='home', chosenKind='Semua',searchTerm='';
function render(next,arg){page=next;if(typeof arg==='string')chosenKind=arg;else if(next==='kamus'&&arg===undefined)chosenKind='Semua';document.querySelectorAll('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.page===page));document.getElementById('nav').classList.remove('nav-open');let out='';
if(page==='home')out=`<section class="hero"><div class="container hero-inner"><div class="hero-copy"><div class="hero-kicker"><span></span> PUSAT INFORMASI STANDAR BIAYA</div><h1>Memahami Standar Biaya, <em>Lebih Mudah.</em></h1><p>Satu pintu untuk menjelajahi definisi, jenis, item, besaran, regulasi, dan referensi standar biaya secara terstruktur.</p><form class="hero-search" id="hero-search-form"><span>⌕</span><input id="hero-query" placeholder="Cari honorarium, perjalanan dinas, SBM, regulasi..." aria-label="Pencarian"><button>Cari Sekarang →</button></form><div class="hero-chips"><span>Penelusuran cepat:</span><a class="preview-route" data-page="kamus" data-query="Honorarium">Honorarium ›</a><a class="preview-route" data-page="kamus" data-query="Perjalanan Dinas">Perjalanan Dinas ›</a><a class="preview-route" data-page="kamus" data-query="Keluaran">Standar Biaya Keluaran ›</a></div></div><div class="hero-art"><div class="hero-graphic"><div class="ring ring-a"></div><div class="ring ring-b"></div><div class="hero-doc doc-a">▤</div><div class="hero-doc doc-b">▥</div><div class="hero-doc doc-c">⚖</div><div class="hero-center">▤<div class="hero-center-rule"></div><span>STANDAR<br>BIAYA</span></div></div></div></div></section><div class="container metric-strip"><div class="metric-item"><strong>6</strong><span>Item Contoh</span></div><div class="metric-item"><strong>2</strong><span>Kartu Regulasi Contoh</span></div><div class="metric-item"><strong>3</strong><span>Kartu Pustaka Contoh</span></div><div class="metric-item"><strong>—</strong><span>Pembaruan Resmi</span></div></div><section class="container section"><div class="section-heading"><div><span class="eyebrow">JELAJAHI INFORMASI</span><h2>Kenali Jenis Standar Biaya</h2><p>Pilih kategori untuk menjelajahi contoh tampilan kamus standar biaya.</p></div></div><div class="type-grid">${[{jenis:'SBM',cls:'icon-blue',icon:'▣',title:'Standar Biaya Masukan',desc:'Informasi satuan biaya masukan dan ketentuannya sesuai referensi sumber resmi.'},{jenis:'SBK',cls:'icon-gold',icon:'▤',title:'Standar Biaya Keluaran',desc:'Kelompok satuan biaya untuk keluaran sesuai ruang lingkup pengaturannya.'},{jenis:'SSB',cls:'icon-teal',icon:'▥',title:'Standar Struktur Biaya',desc:'Informasi standar komposisi atau struktur biaya berdasarkan peraturan yang berlaku.'}].map(card).join('')}</div></section><section class="section section-tint"><div class="container"><div class="section-heading"><div><span class="eyebrow">KAMUS DIGITAL</span><h2>Item Standar Biaya</h2><p>Gambaran katalog yang dilengkapi pencarian dan filter.</p></div><button class="preview-link-btn preview-route" data-page="kamus">Lihat Semua Item →</button></div><div class="featured-list">${ITEMS.slice(0,4).map(x=>`<a class="featured-row preview-route" data-page="detail" data-id="${x.id}"><div class="featured-symbol">▤</div><div><h3>${esc(x.nama)}</h3><p>${esc(x.kelompok)} • ${esc(x.satuan)}</p></div>${badge(x.jenis)}<span class="featured-arrow">›</span></a>`).join('')}</div></div></section><section class="container section"><div class="promo-grid"><div class="promo-card promo-dark"><span class="eyebrow">REFERENSI HUKUM</span><h2>Regulasi dalam Satu Akses</h2><p>Telusuri referensi hukum dan status keberlakuan setelah data resmi dimuat.</p><a class="preview-route" data-page="regulasi">Telusuri Regulasi →</a></div><div class="promo-card promo-light"><span class="eyebrow">PUSAT PENGETAHUAN</span><h2>Perpustakaan Digital</h2><p>Kumpulan bahan paparan, pedoman, dan kajian terpublikasi dalam satu portal.</p><a class="preview-route" data-page="pustaka">Buka Pustaka →</a></div></div></section>`;
if(page==='mengenal')out=pageHero('PENGETAHUAN DASAR','Mengenal Standar Biaya','Pemahaman umum dan fungsi standar biaya dalam penyusunan anggaran.')+`<section class="container section article-shell"><div class="article-main"><h2>Apa itu Standar Biaya?</h2><p>Standar biaya merupakan salah satu instrumen acuan dalam penganggaran pemerintah. Definisi hukum setiap kelompok mengacu pada regulasi yang berlaku.</p><div class="notice"><span>ⓘ</span><p>Konten ini adalah ringkasan edukatif dan tidak menggantikan bunyi peraturan resmi.</p></div><h2>Kelompok Utama</h2><div class="article-cards"><div>${badge('SBM')}<h3>Standar Biaya Masukan</h3><p>Satuan biaya masukan sesuai lingkup penetapannya.</p></div><div>${badge('SBK')}<h3>Standar Biaya Keluaran</h3><p>Standar biaya yang berkenaan dengan suatu keluaran.</p></div><div>${badge('SSB')}<h3>Standar Struktur Biaya</h3><p>Standar yang berkaitan dengan struktur atau komposisi biaya.</p></div></div><h2>Cara Menggunakan Portal</h2><ol class="steps"><li>Cari item atau pilih kategori standar biaya.</li><li>Tentukan tahun anggaran, satuan, dan wilayah jika diperlukan.</li><li>Periksa besaran biaya dan regulasi yang mendasarinya.</li><li>Gunakan dokumen sumber resmi sebagai rujukan utama.</li></ol></div><aside class="article-side"><h3>Akses Cepat</h3><a class="preview-route" data-page="kamus">Kamus Biaya →</a><a class="preview-route" data-page="regulasi">Dasar Hukum →</a><a class="preview-route" data-page="dashboard">Dashboard →</a></aside></section>`;
if(page==='kamus')out=pageHero('PENCARIAN TERPADU','Kamus Standar Biaya','Telusuri item standar biaya menggunakan filter jenis dan kata kunci.')+`<section class="container section"><div class="preview-form"><input id="filter-query" placeholder="Cari nama item, kategori, atau satuan..." value="${esc(searchTerm)}" aria-label="Cari item"><select id="filter-kind" aria-label="Jenis"><option>Semua</option><option ${chosenKind==='SBM'?'selected':''}>SBM</option><option ${chosenKind==='SBK'?'selected':''}>SBK</option><option ${chosenKind==='SSB'?'selected':''}>SSB</option></select></div><div class="catalog-toolbar"><span id="resultcount">6 item contoh</span><button class="preview-table-btn" id="reset">Atur Ulang Filter</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Nama Item / Kelompok</th><th>Jenis</th><th>Satuan</th><th>Status</th><th></th></tr></thead><tbody id="item-rows"></tbody></table></div><div class="preview-tip">Tidak tersedia besaran nominal pada data demonstrasi. Integrasikan sumber resmi untuk menampilkan angka.</div></section>`;
if(page==='detail'){const x=ITEMS.find(z=>z.id===window.selectedId)||ITEMS[0];out=pageHero('RINCIAN ITEM',esc(x.nama),esc(x.kelompok)+' / '+esc(x.satuan))+`<section class="container section"><button class="preview-link-btn preview-route" data-page="kamus">← Kembali ke Kamus</button><div class="detail-grid" style="margin-top:23px"><div class="detail-main"><div class="panel"><h2>Deskripsi & Ketentuan</h2><p>${esc(x.desc)}</p><div class="detail-facts"><div><span>Jenis</span><b>${x.jenis}</b></div><div><span>Satuan</span><b>${esc(x.satuan)}</b></div><div><span>ID item</span><b>${x.id}</b></div><div><span>Status</span><b>Contoh</b></div></div></div><div class="panel"><h2>Besaran Biaya</h2><div class="empty"><h3>Belum ada besaran resmi</h3><p>Besaran akan berasal dari tab BESARAN_BIAYA.</p></div></div><div class="panel"><h2>Dasar Hukum</h2><div class="empty"><h3>Belum ada regulasi terhubung</h3><p>Koneksikan tab RELASI_REGULASI.</p></div></div></div><aside class="side-note"><h3>Periksa Sumber Resmi</h3><p>Jangan menggunakan item contoh sebagai dasar penganggaran.</p></aside></div></section>`;}
if(page==='regulasi')out=pageHero('DASAR HUKUM','Pustaka Regulasi','Penelusuran regulasi dan dokumen pendukung standar biaya.')+`<section class="container section"><div class="preview-form"><input id="reg-query" placeholder="Cari regulasi..." aria-label="Cari regulasi"><select id="reg-year"><option>Semua Tahun</option><option>2026</option><option>2025</option></select></div><div id="reg-results"></div></section>`;
if(page==='dashboard')out=pageHero('ANALITIK & MONITORING','Dashboard Standar Biaya','Contoh indikator jumlah catatan yang dapat dihasilkan dari sumber data.')+`<section class="container section"><div class="dashboard-intro"><div><h2>Ringkasan Data Simulasi</h2><p>Hanya untuk menguji tampilan dashboard.</p></div><span class="badge warning">DATA SIMULASI</span></div><div class="stat-grid"><div class="stat-card"><div class="stat-value">6</div><div class="stat-label">Total Item Contoh</div></div><div class="stat-card"><div class="stat-value">4</div><div class="stat-label">Item SBM Contoh</div></div><div class="stat-card"><div class="stat-value">1</div><div class="stat-label">Item SBK Contoh</div></div><div class="stat-card"><div class="stat-value">2</div><div class="stat-label">Referensi Placeholder</div></div></div><div class="chart-grid"><div class="preview-dashboard-panel"><h3>Komposisi Jenis Standar Biaya</h3>${[['SBM',4,67],['SBK',1,17],['SSB',1,17]].map(x=>`<div class="preview-chart-row"><span>${x[0]}</span><div class="preview-bar"><span style="width:${x[2]}%"></span></div><b>${x[1]}</b></div>`).join('')}</div><div class="preview-dashboard-panel"><h3>Perkembangan Data</h3><p class="preview-footer-note">Grafik ini hanya desain indikator, bukan tren resmi.</p>${[['2024',2,33],['2025',3,50],['2026',6,100]].map(x=>`<div class="preview-chart-row"><span>${x[0]}</span><div class="preview-bar"><span style="width:${x[2]}%"></span></div><b>${x[1]}</b></div>`).join('')}</div></div><div class="notice" style="margin-top:20px"><p>Dashboard bukan laporan realisasi anggaran dan tidak boleh digunakan untuk menarik kesimpulan fiskal dari data simulasi.</p></div></section>`;
if(page==='pustaka')out=pageHero('DOKUMENTASI & PENGETAHUAN','Pustaka Digital','Ruang informasi untuk bahan paparan, pedoman, kajian dan referensi lainnya.')+`<section class="container section"><div class="preview-tabs" id="doc-tabs">${['Semua','Paparan','Pedoman','Kajian'].map((x,i)=>`<button data-cat="${x}" class="${i===0?'active':''}">${x}</button>`).join('')}</div><div class="doc-grid" id="doc-results"></div></section>`;
if(page==='faq')out=pageHero('BANTUAN & INFORMASI','Tanya Jawab','Jawaban atas pertanyaan umum mengenai penggunaan kamus.')+`<section class="container section faq-container">${FAQ.map((x,i)=>`<div class="faq-item"><button class="faq-toggle" data-faq="${i}" aria-expanded="false"><span>${esc(x[0])}</span><span>⌄</span></button><div class="preview-faq-content" id="faq-${i}" hidden>${esc(x[1])}</div></div>`).join('')}</section>`;
document.getElementById('app').innerHTML=out; bindInteractions();window.scrollTo(0,0);}
function drawItems(){const q=(document.getElementById('filter-query')?.value||'').toLowerCase(),k=document.getElementById('filter-kind')?.value||'Semua';const items=ITEMS.filter(x=>(k==='Semua'||x.jenis===k)&&`${x.nama} ${x.kelompok} ${x.satuan}`.toLowerCase().includes(q));document.getElementById('resultcount').textContent=items.length+' item contoh';document.getElementById('item-rows').innerHTML=items.length?items.map(x=>`<tr><td><a class="item-link preview-route" data-page="detail" data-id="${x.id}">${esc(x.nama)}</a><span class="subline">${esc(x.kelompok)}</span></td><td>${badge(x.jenis)}</td><td>${esc(x.satuan)}</td><td>${badge('Contoh')}</td><td><a class="preview-route" data-page="detail" data-id="${x.id}">↗</a></td></tr>`).join(''):'<tr><td colspan="5">Tidak ada item yang sesuai.</td></tr>';}
function drawRegs(){const q=(document.getElementById('reg-query')?.value||'').toLowerCase(),y=document.getElementById('reg-year')?.value;document.getElementById('reg-results').innerHTML=REGS.filter(r=>(y==='Semua Tahun'||y===r.tahun)&&`${r.judul} ${r.jenis}`.toLowerCase().includes(q)).map(r=>`<div class="reg-card" style="margin-bottom:13px"><span class="reg-icon">⚖</span><div class="reg-body"><div class="reg-meta">${badge(r.jenis)} <span>${r.tahun}</span> ${badge('Contoh')}</div><h3>${esc(r.judul)}</h3><p>${r.jenis} No. ${r.nomor} Tahun ${r.tahun}</p></div><span class="reg-disabled">Belum ada tautan resmi</span></div>`).join('')||'<div class="empty">Regulasi tidak ditemukan.</div>'}
function drawDocs(cat='Semua'){const docs=DOCS.filter(x=>cat==='Semua'||x.kategori===cat);document.getElementById('doc-results').innerHTML=docs.map(x=>`<article class="doc-card"><div class="doc-visual">▤<span>${x.kategori.toUpperCase()}</span></div><div class="doc-card-body"><div class="doc-meta">${x.tahun} • ${x.kategori}</div><h3>${esc(x.judul)}</h3><p>${esc(x.ket)}</p><span class="doc-unavailable">Belum ada file (contoh)</span></div></article>`).join('')}
function bindInteractions(){document.querySelectorAll('.preview-route').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();if(el.dataset.id)window.selectedId=el.dataset.id;searchTerm=el.dataset.query||'';render(el.dataset.page||'home',el.dataset.jenis)}));const sf=document.getElementById('hero-search-form');if(sf)sf.addEventListener('submit',e=>{e.preventDefault();searchTerm=document.getElementById('hero-query').value;render('kamus')});if(page==='kamus'){drawItems();document.getElementById('item-rows').addEventListener('click',e=>{const t=e.target.closest('.preview-route');if(t){e.preventDefault();window.selectedId=t.dataset.id;render('detail')}});const q=document.getElementById('filter-query'),k=document.getElementById('filter-kind');q.addEventListener('input',()=>{searchTerm=q.value;drawItems()});k.addEventListener('change',()=>{chosenKind=k.value;drawItems()});document.getElementById('reset').addEventListener('click',()=>{q.value='';k.value='Semua';searchTerm='';chosenKind='Semua';drawItems()})}if(page==='regulasi'){drawRegs();document.getElementById('reg-query').addEventListener('input',drawRegs);document.getElementById('reg-year').addEventListener('change',drawRegs)}if(page==='pustaka'){drawDocs();document.querySelectorAll('#doc-tabs button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#doc-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');drawDocs(b.dataset.cat)}))}if(page==='faq'){document.querySelectorAll('.faq-toggle').forEach(b=>b.addEventListener('click',()=>{const x=document.getElementById('faq-'+b.dataset.faq);x.hidden=!x.hidden;b.setAttribute('aria-expanded',String(!x.hidden))}))}}
document.getElementById('hamburger').addEventListener('click',()=>document.getElementById('nav').classList.toggle('nav-open'));
document.querySelectorAll('header .preview-route,footer .preview-route').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();searchTerm='';render(el.dataset.page||'home')}));
render('home');
</script></body></html>'''
(root/'preview-offline.html').write_text(html.replace('__STYLES__',css),encoding='utf-8')
print('Wrote offline preview:',(root/'preview-offline.html').stat().st_size,'bytes')
